<?php $db = sqlite_open(":memory:"); sqlite_exec($db, "CREATE TABLE u (id INTEGER PRIMARY KEY, name TEXT, age INT)"); sqlite_exec($db, "INSERT INTO u (name, age) VALUES (:name, :age)", ["name" => "bo", "age" => 31]); sqlite_exec($db, 'INSERT INTO u (name, age) VALUES (@n, :a)', ['@n' => 'cy', 'a' => 40]); var_dump(sqlite_query($db, "SELECT name, age FROM u WHERE age > :min ORDER BY id", [":min" => 30]));
